        R.func_attr({"relax.force_pure": True, "tir_non_negative_var": ["vocab_size"], "tir_var_upper_bound": {"batch_size": 128, "num_positions": 768, "num_samples": 128}})
        cls = Module
        storage: R.Object = R.memory.alloc_storage(R.shape([128 * vocab_size * 4 * 8 + 8388608 + 128 * vocab_size * 12]), R.prim_value(0), R.str("global"), R.dtype("uint8"))
