        storage1: R.Object = R.memory.alloc_storage(R.shape([128 * vocab_size * 4]), R.prim_value(0), R.str("global"), R.dtype("int32"))
        alloc: R.Tensor((batch_size, vocab_size), dtype="int32") = R.memory.alloc_tensor(storage1, R.prim_value(0), R.shape([batch_size, vocab_size]), R.dtype("int32"))
        cls.argsort_thrust(probs, lv, alloc)
        lv1: R.Tensor((batch_size, vocab_size), dtype="int32") = alloc
        storage2: R.Object = R.memory.alloc_storage(R.shape([128 * vocab_size * 4]), R.prim_value(0), R.str("global"), R.dtype("float32"))
        alloc1: R.Tensor((batch_size, vocab_size), dtype="float32") = R.memory.alloc_tensor(storage2, R.prim_value(0), R.shape([batch_size, vocab_size]), R.dtype("float32"))
        cls.take_sorted_probs(probs, lv1, alloc1)
        lv2: R.Tensor((batch_size, vocab_size), dtype="float32") = alloc1
        gv1: R.Tuple(R.Tensor((batch_size, vocab_size), dtype="float32"), R.Tensor((batch_size, vocab_size), dtype="int32")) = lv2, lv1
        return gv1

